import{_ as a,o as d,c as r,a0 as e}from"./chunks/framework.DzvPB4Y-.js";const c=JSON.parse('{"title":"从业务场景选择框架","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/index.md","filePath":"zh-cn/frameworks/index.md"}'),h={name:"zh-cn/frameworks/index.md"};function i(o,t,n,l,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="从业务场景选择框架" tabindex="-1">从业务场景选择框架 <a class="header-anchor" href="#从业务场景选择框架" aria-label="Permalink to &quot;从业务场景选择框架&quot;">​</a></h1><p>业务框架把可复用的领域模型、约束、候选生成和求解编排组合起来。你提供业务数据、选择目标并接入求解器，不必从决策变量开始重写整个模型。</p><p>这条学习路线与<a href="/ospf/zh-cn/guide/getting-started.html">从 Core 开始建模</a>并行：已有合适的领域框架时先复用；问题超出框架范围时，再组合上下文或自行建模。不要求先读完 DDD 或列生成理论。</p><h2 id="我的问题该选哪一个" tabindex="-1">我的问题该选哪一个？ <a class="header-anchor" href="#我的问题该选哪一个" aria-label="Permalink to &quot;我的问题该选哪一个？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你需要做出的决策</th><th>框架</th><th>第一课</th></tr></thead><tbody><tr><td>已有长条物品如何放进有限长度的容器</td><td><a href="./bpp1d/">一维装箱 BPP1D</a></td><td><a href="./bpp1d/first-packing.html">物品、间距与容器库存</a></td></tr><tr><td>已有二维物品如何排到有限板面上</td><td><a href="./bpp2d/">二维装箱 BPP2D</a></td><td><a href="./bpp2d/first-layout.html">矩形排样与结果检查</a></td></tr><tr><td>货物如何装入箱体或集装箱</td><td><a href="./bpp3d/">三维装箱 BPP3D</a></td><td><a href="./bpp3d/first-loading.html">从长方体装载开始</a></td></tr><tr><td>原料如何分切以满足不同宽度的订单</td><td><a href="./csp1d/">一维分切 CSP1D</a></td><td><a href="./csp1d/first-slitting.html">产品需求与切割方案</a></td></tr><tr><td>定尺板材或卷材如何裁成矩形产品</td><td><a href="./csp2d/">二维套裁 CSP2D</a></td><td><a href="./csp2d/first-cutting.html">板材、图案与生产数量</a></td></tr><tr><td>活动何时执行，同时占用哪些资源</td><td><a href="./gantt/">时间与资源排程 Gantt</a></td><td><a href="./gantt/first-schedule.html">有限候选活动排程</a></td></tr><tr><td>供需、流量、路径和网络建设如何配置</td><td><a href="./network/">网络优化 Network</a></td><td><a href="./network/first-flow.html">先解决一个小型流问题</a></td></tr></tbody></table><h2 id="容易选错的两个地方" tabindex="-1">容易选错的两个地方 <a class="header-anchor" href="#容易选错的两个地方" aria-label="Permalink to &quot;容易选错的两个地方&quot;">​</a></h2><h3 id="装箱与下料-看业务语义-不只看维数" tabindex="-1">装箱与下料：看业务语义，不只看维数 <a class="header-anchor" href="#装箱与下料-看业务语义-不只看维数" aria-label="Permalink to &quot;装箱与下料：看业务语义，不只看维数&quot;">​</a></h3><p>BPP 侧重已有物品的放置与装载，CSP 侧重原料加工、产品需求和方案产出。BPP2D 也支持间距、刀缝和余料报告，CSP2D 的定尺模式也具有二维装箱结构，不能简单按“有没有刀缝”选择。</p><p>如果你需要解释“这个图案使用几次，生产多少产品，是否允许超产，是否满足设备工艺”，优先考察 CSP；如果重点是“这些物品放在哪块板、哪个箱、什么坐标和朝向”，优先考察 BPP。随后再核对具体能力边界。</p><h3 id="gantt-与-network-时间编排和网络决策可以组合" tabindex="-1">Gantt 与 Network：时间编排和网络决策可以组合 <a class="header-anchor" href="#gantt-与-network-时间编排和网络决策可以组合" aria-label="Permalink to &quot;Gantt 与 Network：时间编排和网络决策可以组合&quot;">​</a></h3><p>Gantt 负责全局活动、资源、依赖和日历；Network 负责拓扑、流、资源路径和结构。维修人员的作业排程可能需要 Gantt 加 Network 路径子问题，普通活动排程则不必引入 Network。车辆路径属于 Network 的进阶入口，不是学习网络流的前置条件。</p><h2 id="建议的学习顺序" tabindex="-1">建议的学习顺序 <a class="header-anchor" href="#建议的学习顺序" aria-label="Permalink to &quot;建议的学习顺序&quot;">​</a></h2><ol><li>阅读<a href="./setup.html">环境与运行方式</a>，添加领域依赖并选择实际后端或明确的默认启发式。</li><li>选择一个框架，先看其输入、输出和不适用范围。</li><li>把第一课的示例函数和启动入口放进小型应用，学习构造输入、调用框架和读取结果。</li><li>完成教程末尾的一个业务变更练习，同时修改相应验收条件。</li><li>阅读<a href="./integration.html">接入自己的业务</a>，再进入对应框架的第二课，把需求、目标和规则替换成自己的数据。</li><li>需要跨领域组合时，再阅读<a href="/ospf/zh-cn/examples/framework-examples.html">综合案例</a>或<a href="/ospf/zh-cn/guide/use-ddd-architecture.html">DDD 架构</a>。</li></ol><h2 id="跑通之后-接着学什么" tabindex="-1">跑通之后，接着学什么？ <a class="header-anchor" href="#跑通之后-接着学什么" aria-label="Permalink to &quot;跑通之后，接着学什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>第二课</th><th>要能回答的问题</th></tr></thead><tbody><tr><td>BPP1D</td><td><a href="./bpp1d/business-scenario.html">多箱型、库存与成本</a></td><td>为什么最少箱数与最小费用会选不同箱型？</td></tr><tr><td>BPP2D</td><td><a href="./bpp2d/business-scenario.html">多板型、旋转与间距</a></td><td>面积够用，为什么仍可能排不下？</td></tr><tr><td>BPP3D</td><td><a href="./bpp3d/business-scenario.html">多箱型与目标配置</a></td><td>默认体积目标和业务费用如何权衡？</td></tr><tr><td>CSP1D</td><td><a href="./csp1d/business-scenario.html">需求口径与业务规则</a></td><td>卷数、重量与方案使用次数怎样对应？</td></tr><tr><td>CSP2D</td><td><a href="./csp2d/business-scenario.html">刀缝、工艺与卷材</a></td><td>图案可放，为什么仍不一定可加工？</td></tr><tr><td>Gantt</td><td><a href="./gantt/business-scenario.html">停机日历与滚动重排</a></td><td>已执行事实、冻结与可调整基线有何区别？</td></tr><tr><td>Network</td><td><a href="./network/business-scenario.html">共享资源、缺货与联合模型</a></td><td>弧容量充分，为什么仍可能无法交付？</td></tr></tbody></table><p>第二课区分源码中的已存在契约与需要你实现的新练习。手算对照不是原生执行日志；用它设计验收，再核对实际求解范围。</p><h2 id="怎样判断自己真的学会了" tabindex="-1">怎样判断自己真的学会了？ <a class="header-anchor" href="#怎样判断自己真的学会了" aria-label="Permalink to &quot;怎样判断自己真的学会了？&quot;">​</a></h2><p>不以“程序返回成功”为唯一标准。你应能解释：输入的数量和单位是什么、哪些规则是硬约束、优化的是什么、结果是否满足需求，以及结果证明到什么范围。</p><table tabindex="0"><thead><tr><th>观察到的结果</th><th>可以得出的结论</th><th>不能直接得出的结论</th></tr></thead><tbody><tr><td>输入校验或模型注册通过</td><td>数据/装配通过对应检查</td><td>已求解、已有可行方案</td></tr><tr><td>mock 回调返回预设解</td><td>编排和提取路径在该夹具下工作</td><td>原生求解器找到该解</td></tr><tr><td>独立枚举验证小实例</td><td>对所枚举的有限问题成立</td><td>任意规模和连续模型都成立</td></tr><tr><td>最终 MILP 返回整数方案</td><td>需继续复核业务可行性与报告</td><td>完整业务问题已证明最优</td></tr><tr><td>受限列池被证明最优</td><td>当前候选模型最优</td><td>未生成的方案也不可能改进</td></tr></tbody></table><p>Kotlin 与 Rust 共用业务解释，但不假设接口或已完成能力完全相同。每课列出各自的真实入口和验证边界；数值验收以该语言的具体用例为准。</p>',20)])])}const b=a(h,[["render",i]]);export{c as __pageData,b as default};
